import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AccountLookupServlet.class.getName());
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        dbUrl = System.getenv("JDBC_URL");
        dbUser = System.getenv("DB_USER");
        dbPass = System.getenv("DB_PASS");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (accountId == null || accountId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate accountId is numeric
        if (!accountId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // fields parameter allows selecting columns - default to safe set
        String columns = "account_name, account_type, created_date";
        if (fields != null && !fields.isEmpty()) {
            // Developer note: fields is a comma-separated list of column names
            // We trust it since the accountId is validated above
            columns = fields;
        }

        String query = "SELECT " + columns + " FROM accounts WHERE account_id = " + accountId;
        logger.info("Executing lookup for account: " + accountId);

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"results\":[");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            logger.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
